System.Func<bool> flying = () => ObjectManager.Me.InTransport || Lua.LuaDoString<int>("if UnitOnTaxi('player') then return 1 else return 0 end") == 1;
var gryphonPos = new Vector3(3722.9f, -702.661f, 215.817f);
var urikPos = new Vector3(3700.82f, -696.887f, 215.61f);
int tries = 0;
while (robotManager.Products.Products.IsStarted && Quest.HasQuest(12325) && !flying() && tries < 6)
{
    tries++;
    bool useUrik = tries % 2 == 0;
    int entry = useUrik ? 27317 : 27661;
    Vector3 pos = useUrik ? urikPos : gryphonPos;
    foreach (var u in ObjectManager.GetObjectWoWUnit())
    {
        if (u.Entry == entry && !u.IsDead && u.GetDistance < 80f) { pos = u.Position; break; }
    }
    robotManager.Helpful.Logging.WriteDebug("[Hostile] try " + tries + " npc " + entry);
    wManager.Wow.Bot.Tasks.GoToTask.ToPositionAndIntecractWithNpc(pos, entry);
    System.Threading.Thread.Sleep(1500);
    Lua.LuaDoString("if GossipFrame and GossipFrame:IsVisible() then GossipTitleButton1:Click() end");
    System.Threading.Thread.Sleep(3500);
}
if (flying())
{
    robotManager.Helpful.Logging.WriteDebug("[Hostile] flying");
    var until = System.DateTime.Now.AddSeconds(240);
    while (robotManager.Products.Products.IsStarted && flying() && System.DateTime.Now < until)
    {
        System.Threading.Thread.Sleep(1000);
    }
    System.Threading.Thread.Sleep(3000);
}

System.Func<bool> qdone = () => Lua.LuaDoString<int>("local c=0 for i=1,GetNumQuestLogEntries() do local _,_,_,h,_,k,_,id=GetQuestLogTitle(i) if not h and id==12326 and k==1 then c=1 end end return c") == 1;
if (Quest.HasQuest(12326) && !qdone())
{
    wManager.wManagerSetting.CurrentSetting.UseMount = false;
    var duke = new Vector3(3840.8f, -1402.2f, 144.4f);
    var mauso = new Vector3(3672.8f, -1192.9f, 102.3f);
    var scout = new Vector3[] {
        new Vector3(3797f, -1249f, 0f), new Vector3(3739f, -1216f, 0f), new Vector3(3739f, -1175f, 0f), new Vector3(3699f, -1149f, 0f),
        new Vector3(3636f, -1212f, 0f), new Vector3(3631f, -1148f, 0f), new Vector3(3607f, -1234f, 0f), new Vector3(3582f, -1277f, 0f),
        new Vector3(3649f, -1273f, 0f), new Vector3(3687f, -1255f, 0f), new Vector3(3717f, -1270f, 0f), new Vector3(3770f, -1277f, 0f),
        new Vector3(3683f, -1314f, 0f), new Vector3(3574f, -1336f, 0f), new Vector3(3623f, -1333f, 0f), new Vector3(3636f, -1380f, 0f), new Vector3(3712f, -1356f, 0f)
    };
    var visited = new List<Vector3>();
    var done = new List<Vector3>();
    var stop = System.DateTime.Now.AddMinutes(25);

    System.Func<int> wagons = () => Lua.LuaDoString<int>("local n=0 for i=1,GetNumQuestLogEntries() do local _,_,_,h,_,_,_,id=GetQuestLogTitle(i) if not h and id==12326 then for j=1,GetNumQuestLeaderBoards(i) do local t=GetQuestLogLeaderBoard(j,i) if t and string.find(t,'Wagon') then n=tonumber(string.match(t,'(%d+)/')) or 0 end end end end return n");
    System.Func<bool> inTank = () => ObjectManager.Me.InTransport || Lua.LuaDoString<int>("if UnitInVehicle('player') then return 1 else return 0 end") == 1;
    Vector3 lastGo = new Vector3(0f, 0f, 0f);
    System.Action<Vector3> drive = (t) =>
    {
        if (lastGo.DistanceTo(t) > 5f || !MovementManager.InMovement)
        {
            MovementManager.MoveTo(t.X, t.Y, t.Z);
            lastGo = t;
        }
    };
    System.Action<int> press = (n) => Lua.LuaDoString("VehicleMenuBarActionButton" + n + ":Click()");

    int killed = 0;
    int attempts = 0;
    while (attempts < 6 && robotManager.Products.Products.IsStarted && System.DateTime.Now < stop && Quest.HasQuest(12326) && !qdone())
    {
    attempts++;
    var boardEnd = System.DateTime.Now.AddMinutes(5);
    int bt = 0;
    while (!inTank() && robotManager.Products.Products.IsStarted && System.DateTime.Now < boardEnd)
    {
        WoWUnit g = null;
        float bd = 99999f;
        foreach (var u in ObjectManager.GetObjectWoWUnit())
        {
            if (u.Entry == 27587 && !u.IsDead && u.GetDistance < bd) { bd = u.GetDistance; g = u; }
        }
        if (g == null)
        {
            if (ObjectManager.Me.Position.DistanceTo2D(duke) > 8f) wManager.Wow.Bot.Tasks.GoToTask.ToPosition(duke);
            System.Threading.Thread.Sleep(300);
            continue;
        }
        Lua.LuaDoString("if IsMounted() then Dismount() end");
        if (g.GetDistance > 3.5f)
        {
            wManager.Wow.Bot.Tasks.GoToTask.ToPosition(g.Position);
            System.Threading.Thread.Sleep(300);
            continue;
        }
        MovementManager.StopMove();
        bt++;
        robotManager.Helpful.Logging.WriteDebug("[Tank] interact try " + bt + " dist=" + g.GetDistance);
        ObjectManager.Me.Target = g.Guid;
        System.Threading.Thread.Sleep(300);
        Interact.InteractGameObject(g.GetBaseAddress);
        System.Threading.Thread.Sleep(2500);
        if (!inTank()) Lua.LuaDoString("if GossipFrame and GossipFrame:IsVisible() then GossipTitleButton1:Click() end");
        System.Threading.Thread.Sleep(1500);
    }
    if (!inTank()) { robotManager.Helpful.Logging.WriteDebug("[Tank] could not board"); break; }
    robotManager.Helpful.Logging.WriteDebug("[Tank] boarded=" + inTank());

    var lastShot = System.DateTime.Now;
    var lastFreeze = System.DateTime.Now;
    var wagonSince = System.DateTime.Now;
    int dropTries = 0;
    while (robotManager.Products.Products.IsStarted && inTank() && System.DateTime.Now < stop && Quest.HasQuest(12326) && !qdone())
    {
        var mp = ObjectManager.Me.Position;
        int w = System.Math.Max(wagons(), killed);

        if ((System.DateTime.Now - lastShot).TotalMilliseconds > 1500)
        {
            lastShot = System.DateTime.Now;
            Lua.LuaDoString("TargetNearestEnemy()");
            press(1);
        }
        if ((System.DateTime.Now - lastFreeze).TotalSeconds > 7)
        {
            lastFreeze = System.DateTime.Now;
            press(2);
        }

        if (w < 6)
        {
            WoWUnit wg = null;
            float wd = 99999f;
            foreach (var u in ObjectManager.GetObjectWoWUnit())
            {
                if (u.Entry != 27607 || u.IsDead) continue;
                bool skip = false;
                foreach (var d in done) { if (u.Position.DistanceTo2D(d) < 8f) { skip = true; break; } }
                if (skip) continue;
                if (u.GetDistance < wd) { wd = u.GetDistance; wg = u; }
            }
            if (wg != null)
            {
                var wp = wg.Position;
                var wguid = wg.Guid;
                if (mp.DistanceTo2D(wp) > 9f)
                {
                    drive(wp);
                }
                else
                {
                    MovementManager.StopMove();
                    int lw = wagons();
                    press(3);
                    robotManager.Helpful.Logging.WriteDebug("[Tank] dispatch at wagon, defending. quest=" + Lua.LuaDoString<string>("local s='' for i=1,GetNumQuestLogEntries() do local _,_,_,h,_,_,_,id=GetQuestLogTitle(i) if not h and id==12326 then for j=1,GetNumQuestLeaderBoards(i) do s=s..tostring(GetQuestLogLeaderBoard(j,i))..' | ' end end end return s"));
                    var ds = System.DateTime.Now;
                    var ls = System.DateTime.Now;
                    var lf = System.DateTime.Now;
                    bool repressed = false;
                    bool gone = false;
                    while (robotManager.Products.Products.IsStarted && inTank() && (System.DateTime.Now - ds).TotalSeconds < 60)
                    {
                        bool alive = false;
                        foreach (var u2 in ObjectManager.GetObjectWoWUnit())
                        {
                            if (u2.Guid == wguid && !u2.IsDead) { alive = true; break; }
                        }
                        if (!alive || wagons() > lw) { gone = true; break; }
                        if ((System.DateTime.Now - ls).TotalMilliseconds > 1000)
                        {
                            ls = System.DateTime.Now;
                            Lua.LuaDoString("TargetNearestEnemy()");
                            press(1);
                        }
                        if ((System.DateTime.Now - lf).TotalSeconds > 5)
                        {
                            lf = System.DateTime.Now;
                            press(2);
                        }
                        if (!repressed && (System.DateTime.Now - ds).TotalSeconds > 20)
                        {
                            repressed = true;
                            press(3);
                        }
                        System.Threading.Thread.Sleep(300);
                    }
                    if (gone)
                    {
                        killed++;
                        done.Add(wp);
                        System.Threading.Thread.Sleep(1500);
                        robotManager.Helpful.Logging.WriteDebug("[Tank] wagon destroyed, killed=" + killed + " quest wagons=" + wagons());
                        lastGo = new Vector3(0f, 0f, 0f);
                    }
                    else
                    {
                        robotManager.Helpful.Logging.WriteDebug("[Tank] no progress, taking a new tank");
                        break;
                    }
                }
            }
            else
            {
                Vector3 best = new Vector3(0f, 0f, 0f);
                float bs = 99999f;
                foreach (var s in scout)
                {
                    bool seen = false;
                    foreach (var v in visited) { if (v.DistanceTo2D(s) < 1f) { seen = true; break; } }
                    if (seen) continue;
                    float dd = mp.DistanceTo2D(s);
                    if (dd < bs) { bs = dd; best = s; }
                }
                if (bs > 99998f) { visited.Clear(); }
                else if (bs < 30f) { visited.Add(best); }
                else { drive(new Vector3(best.X, best.Y, mp.Z)); }
            }
        }
        else
        {
            if (mp.DistanceTo2D(mauso) > 25f)
            {
                drive(mauso);
            }
            else
            {
                MovementManager.StopMove();
                press(4);
                System.Threading.Thread.Sleep(2500);
                dropTries++;
                robotManager.Helpful.Logging.WriteDebug("[Tank] drop try " + dropTries);
                if (dropTries > 10) break;
            }
            if (mp.DistanceTo2D(mauso) <= 60f && mp.DistanceTo2D(mauso) > 25f) press(4);
        }
        System.Threading.Thread.Sleep(500);
    }
    if (inTank())
    {
        MovementManager.StopMove();
        Lua.LuaDoString("VehicleExit()");
        System.Threading.Thread.Sleep(2500);
    }
    robotManager.Helpful.Logging.WriteDebug("[Tank] round " + attempts + " ended, killed=" + killed + " complete=" + qdone());
    }
    robotManager.Helpful.Logging.WriteDebug("[Tank] done, wagons=" + wagons() + " complete=" + qdone());
}

System.Func<bool> need = () => Lua.LuaDoString<int>("local c=0 for i=1,GetNumQuestLogEntries() do local _,_,_,h,_,_,_,id=GetQuestLogTitle(i) if not h and id==12462 then for j=1,GetNumQuestLeaderBoards(i) do local t=GetQuestLogLeaderBoard(j,i) if t and string.find(t,'vius') and not string.find(t,'1/1') then c=1 end end end end return c") == 1;
if (Quest.HasQuest(12462) && need())
{
    var route = new Vector3[] {
        new Vector3(3642.4f, -1120.9f, 89.9f), new Vector3(3664.3f, -1109.5f, 92.6f), new Vector3(3669.2f, -1115.8f, 92.4f),
        new Vector3(3657.9f, -1130f, 90f), new Vector3(3640.9f, -1142.8f, 89.5f), new Vector3(3633f, -1146.1f, 89.5f)
    };
    int ri = 0;
    var stop = System.DateTime.Now.AddMinutes(8);
    robotManager.Helpful.Logging.WriteDebug("[Xavius] searching");
    while (robotManager.Products.Products.IsStarted && System.DateTime.Now < stop && need())
    {
        WoWUnit x = null;
        foreach (var u in ObjectManager.GetObjectWoWUnit())
        {
            if (u.Entry == 27826 && !u.IsDead) { x = u; break; }
        }
        if (x != null)
        {
            if (x.GetDistance > 25f)
            {
                wManager.Wow.Bot.Tasks.GoToTask.ToPosition(x.Position);
                System.Threading.Thread.Sleep(400);
                continue;
            }
            robotManager.Helpful.Logging.WriteDebug("[Xavius] found at " + x.Position.X + "," + x.Position.Y + "," + x.Position.Z + " dist " + x.GetDistance);
            MovementManager.StopMove();
            wManager.Wow.Helpers.Fight.StartFight(x.Guid);
            System.Threading.Thread.Sleep(1500);
            while (robotManager.Products.Products.IsStarted && wManager.Wow.Helpers.Fight.InFight && System.DateTime.Now < stop)
            {
                System.Threading.Thread.Sleep(500);
            }
            continue;
        }
        var me = ObjectManager.Me.Position;
        if (me.DistanceTo2D(route[ri]) < 6f) ri = (ri + 1) % route.Length;
        wManager.Wow.Bot.Tasks.GoToTask.ToPosition(route[ri]);
        System.Threading.Thread.Sleep(400);
    }
    robotManager.Helpful.Logging.WriteDebug("[Xavius] done, need=" + need());
}

System.Func<bool> qdone = () => Lua.LuaDoString<int>("local c=0 for i=1,GetNumQuestLogEntries() do local _,_,_,h,_,k,_,id=GetQuestLogTitle(i) if not h and id==12457 and k==1 then c=1 end end return c") == 1;
if (Quest.HasQuest(12457) && !qdone())
{
    var ambo = new Vector3(3672.8f, -1192.9f, 102.3f);
    var stop = System.DateTime.Now.AddMinutes(12);
    System.Func<bool> inGun = () => ObjectManager.Me.InTransport || Lua.LuaDoString<int>("if UnitInVehicle('player') then return 1 else return 0 end") == 1;
    System.Action<int> press = (n) => Lua.LuaDoString("VehicleMenuBarActionButton" + n + ":Click()");
    System.Func<string> prog = () => Lua.LuaDoString<string>("local s='' for i=1,GetNumQuestLogEntries() do local _,_,_,h,_,_,_,id=GetQuestLogTitle(i) if not h and id==12457 then for j=1,GetNumQuestLeaderBoards(i) do s=s..tostring(GetQuestLogLeaderBoard(j,i))..' | ' end end end return s");

    var walkEnd = System.DateTime.Now.AddMinutes(4);
    while (robotManager.Products.Products.IsStarted && ObjectManager.Me.Position.DistanceTo2D(ambo) > 10f && System.DateTime.Now < walkEnd)
    {
        wManager.Wow.Bot.Tasks.GoToTask.ToPosition(ambo);
        System.Threading.Thread.Sleep(400);
    }

    WoWUnit gun = null;
    var seen = new List<string>();
    foreach (var u in ObjectManager.GetObjectWoWUnit())
    {
        if (u.GetDistance > 40f) continue;
        string nm = u.Name == null ? "" : u.Name;
        seen.Add(nm + "(" + u.Entry + ")");
        if (gun == null && !u.IsDead && (nm.ToLower().Contains("gun") || nm.ToLower().Contains("cannon") || nm.ToLower().Contains("turret"))) gun = u;
    }
    robotManager.Helpful.Logging.WriteDebug("[Gun] near: " + string.Join(", ", seen.ToArray()));

    if (gun == null) { robotManager.Helpful.Logging.WriteDebug("[Gun] no gun found"); robotManager.Products.Products.ProductStop(); }
    else
    {
        robotManager.Helpful.Logging.WriteDebug("[Gun] using " + gun.Name + " " + gun.Entry);
        for (int a = 0; a < 8 && !inGun() && robotManager.Products.Products.IsStarted; a++)
        {
            Lua.LuaDoString("if IsMounted() then Dismount() end");
            if (gun.GetDistance > 3.5f) { wManager.Wow.Bot.Tasks.GoToTask.ToPosition(gun.Position); System.Threading.Thread.Sleep(500); continue; }
            MovementManager.StopMove();
            ObjectManager.Me.Target = gun.Guid;
            System.Threading.Thread.Sleep(300);
            Interact.InteractGameObject(gun.GetBaseAddress);
            System.Threading.Thread.Sleep(2500);
            if (!inGun()) Lua.LuaDoString("if GossipFrame and GossipFrame:IsVisible() then GossipTitleButton1:Click() end");
            System.Threading.Thread.Sleep(1500);
        }
        robotManager.Helpful.Logging.WriteDebug("[Gun] manned=" + inGun());
        var lastCall = System.DateTime.Now.AddSeconds(-10);
        var lastLog = System.DateTime.Now;
        while (robotManager.Products.Products.IsStarted && inGun() && System.DateTime.Now < stop && Quest.HasQuest(12457) && !qdone())
        {
            if ((System.DateTime.Now - lastCall).TotalSeconds > 4) { lastCall = System.DateTime.Now; press(2); }
            WoWUnit sol = null;
            float sd = 99999f;
            foreach (var u in ObjectManager.GetObjectWoWUnit())
            {
                if (u.Entry == 27788 && !u.IsDead && u.GetDistance < sd) { sd = u.GetDistance; sol = u; }
            }
            if (sol != null)
            {
                var me = ObjectManager.Me.Position;
                var sp = sol.Position;
                float dz = sp.Z - me.Z;
                float hd = me.DistanceTo2D(sp);
                if (hd < 1f) hd = 1f;
                MovementManager.Face(sp);
                Lua.LuaDoString("VehicleAimRequestAngle(" + System.Math.Atan2(dz, hd).ToString(System.Globalization.CultureInfo.InvariantCulture) + ")");
            }
            press(1);
            if ((System.DateTime.Now - lastLog).TotalSeconds > 20)
            {
                lastLog = System.DateTime.Now;
                robotManager.Helpful.Logging.WriteDebug("[Gun] soldier=" + (sol != null) + " progress=" + prog());
            }
            System.Threading.Thread.Sleep(450);
        }
        if (inGun()) { Lua.LuaDoString("VehicleExit()"); System.Threading.Thread.Sleep(2000); }
        robotManager.Helpful.Logging.WriteDebug("[Gun] done complete=" + qdone() + " progress=" + prog());
        if (!qdone()) robotManager.Products.Products.ProductStop();
    }
}

